MOD = 10**9 + 7

def factorize(n):
    factors = []
    i = 2
    temp = n
    while i * i <= temp:
        if temp % i == 0:
            count = 0
            while temp % i == 0:
                temp //= i
                count += 1
            factors.append((i, count))
        i += 1
    if temp > 1:
        factors.append((temp, 1))
    return factors

def generate_divisors(factors):
    divisors = [1]
    for (p, exp) in factors:
        current_divisors = []
        for d in divisors:
            current_d = d
            for i in range(0, exp + 1):
                current_divisors.append(current_d * (p ** i))
        divisors = current_divisors
    return divisors

def multiplicative_order(k, p):
    phi = p - 1
    factors = factorize(phi)
    divisors = generate_divisors(factors)
    divisors = list(set(divisors))
    divisors.sort()
    for d in divisors:
        if pow(k, d, p) == 1:
            return d
    return phi

def solve():
    import sys
    p, k = map(int, sys.stdin.read().split())
    if k == 0:
        print(pow(p, p-1, MOD))
        return
    if k % p == 1:
        print(pow(p, p, MOD))
        return
    m = multiplicative_order(k, p)
    c = (p - 1) // m
    print(pow(p, c, MOD))

