    ptr += n

    # Precompute log_table
    n_initial = n
    log_table = [0] * (n_initial + 2)
    for i in range(2, n_initial + 1):
        log_table[i] = log_table[i // 2] + 1

    # Compute max_log
    max_log = 0
    while (1 << max_log) <= n_initial:
        max_log += 1
    max_log -= 1

    # Build min sparse table
    table_min = [[0] * n_initial for _ in range(max_log + 1)]
    for i in range(n_initial):
        table_min[0][i] = i

    for k in range(1, max_log + 1):
        for i in range(n_initial):
            if i + (1 << (k-1)) < n_initial:
                j = i + (1 << (k-1))
                if a[table_min[k-1][i]] <= a[table_min[k-1][j]]:
                    table_min[k][i] = table_min[k-1][i]
                else:
                    table_min[k][i] = table_min[k-1][j]
            else:
                table_min[k][i] = table_min[k-1][i]

    # Build max sparse table
    table_max = [[0] * n_initial for _ in range(max_log + 1)]
    for i in range(n_initial):
        table_max[0][i] = i

    for k in range(1, max_log + 1):
        for i in range(n_initial):
            if i + (1 << (k-1)) < n_initial:
                j = i + (1 << (k-1))
                if a[table_max[k-1][i]] >= a[table_max[k-1][j]]:
                    table_max[k][i] = table_max[k-1][i]
                else:
                    table_max[k][i] = table_max[k-1][j]
            else:
                table_max[k][i] = table_max[k-1][i]

    # Process queries
