import sys

def solve_rebus(rebus_line):
    parts = rebus_line.split()
    n = int(parts[-1])
    ops = []
    for i in range(0, len(parts) - 2, 2):
        ops.append(parts[i + 1])

    num_questions = (len(parts) - 2) // 2 + 1

    # The minimal sum is when all are 1
    min_sum = 1
    for op in ops:
        if op == '-':
            min_sum -= 1
        else:
            min_sum += 1

    if min_sum > n or n < 1:
        return "Impossible", ""

    values = [1] * num_questions
    current = min_sum
    for i in range(num_questions - 1):
        diff = n - current
        if ops[i] == '+':
            values[i + 1] += diff
        else:
            values[i + 1] += diff
        current = n

    result = []
    for i in range(num_questions):
        result.append(str(values[i]))
        if i < len(ops):
            result.append(ops[i])
    result.append('=')
    result.append(str(n))

    return "Possible", ' '.join(result)

