sys.setrecursionlimit(1 << 25)

class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.data = data
        self.tree = [ (0, 0) ] * (4 * self.n)
        self.build(0, 0, self.n - 1)

    def build(self, node, l, r):
        if l == r:
            val = self.data[l]
            self.tree[node] = (val, l + 1)  # station index is l+1
            return
        mid = (l + r) // 2
        left_node = 2 * node + 1
        right_node = 2 * node + 2
        self.build(left_node, l, mid)
        self.build(right_node, mid + 1, r)
        left_val, left_idx = self.tree[left_node]
        right_val, right_idx = self.tree[right_node]
        if left_val > right_val:
            self.tree[node] = (left_val, left_idx)
        elif right_val > left_val:
            self.tree[node] = (right_val, right_idx)
        else:
            self.tree[node] = (left_val, max(left_idx, right_idx))

    def query(self, ql, qr):
        return self._query(0, 0, self.n - 1, ql, qr)

    def _query(self, node, node_l, node_r, ql, qr):
        if node_r < ql or node_l > qr:
            return (-float('inf'), -1)
        if ql <= node_l and node_r <= qr:
            return self.tree[node]
        mid = (node_l + node_r) // 2
        left_val, left_idx = self._query(2 * node + 1, node_l, mid, ql, qr)
        right_val, right_idx = self._query(2 * node + 2, mid + 1, node_r, ql, qr)
        if left_val > right_val:
            return (left_val, left_idx)
        elif right_val > left_val:
            return (right_val, right_idx)
        else:
            return (left_val, max(left_idx, right_idx))

