import sys
from collections import defaultdict

def get_pattern(num, max_len):
    s = str(num)
    pattern = []
    for c in reversed(s):
        if int(c) % 2 == 0:
            pattern.append('0')
        else:
            pattern.append('1')
    while len(pattern) < max_len:
        pattern.append('0')
    return ''.join(reversed(pattern[:max_len]))

def main():
    input = sys.stdin.read
    data = input().splitlines()
    t = int(data[0])
    max_len = 18
    from collections import defaultdict
    multiset = defaultdict(int)
    queries = data[1:]
    patterns = set()

    for line in queries:
        parts = line.split()
        op = parts[0]
        val = parts[1]

        if op == '+':
            num = int(val)
            multiset[num] += 1
        elif op == '-':
            num = int(val)
            multiset[num] -= 1
            if multiset[num] == 0:
                del multiset[num]
        elif op == '?':
            s = val
            pattern = s
            while len(pattern) < max_len:
                pattern = '0' + pattern
            pattern = pattern[-max_len:]
            count = 0
            for num in multiset:
                num_pattern = get_pattern(num, max_len)
                if num_pattern == pattern:
                    count += multiset[num]
            print(count)

if __name__ == "__main__":
    main()

