            right = max_side
            left = x - right
        lzeros, lones = compute(left, prefer_left)
        rzeros, rones = compute(right, prefer_left)
        zeros = left * 1 + lzeros + rzeros
        ones = right * 1 + lones + rones
        return (zeros, ones)

