    result = [False] * (n + 1)

    for i in range(1, n + 1):
        if visited[i] == 0:
            stack = []
            current = i
            while True:
                if visited[current] == 1:
                    # Found a cycle
                    idx = stack.index(current)
                    # Mark all nodes from idx to end as False
                    for node in stack[idx:]:
                        visited[node] = 2
                        result[node] = False
                    # Truncate the stack
                    stack = stack[:idx]
                    # Update current if stack is not empty
                    if stack:
                        current = stack[-1]
                    else:
