import sys
import itertools

def min_operations(n, m, strings):
    digits = set('0123456789')
    letters = set('abcdefghijklmnopqrstuvwxyz')
    symbols = {'#', '*', '&'}

    has_digit = [i for i, s in enumerate(strings) if any(c in digits for c in s)]
    has_letter = [i for i, s in enumerate(strings) if any(c in letters for c in s)]
    has_symbol = [i for i, s in enumerate(strings) if any(c in symbols for c in s)]

    total_ops = float('inf')

    for d in has_digit:
        for l in has_letter:
            for s in has_symbol:
                if {d, l, s} == set(range(n)):
                    continue  # All are the same position, invalid selection
                ops = 0
                selected = set([d, l, s])
                for i in range(n):
                    if i in selected:
                        continue
                    ops += 0  # No move needed for these positions since we only count moves for selected ones
                for idx in [d, l, s]:
                    pos = 0
                    while strings[idx][pos] != (digits if idx == d else letters if idx == l else symbols).pop():
                        pos = (pos + 1) % m
                    ops += min(pos, m - pos)
                total_ops = min(total_ops, ops)

    return total_ops

def main():
    n, m = map(int, sys.stdin.readline().split())
    strings = [sys.stdin.readline().strip() for _ in range(n)]
    print(min_operations(n, m, strings))

if __name__ == "__main__":
    main()

