import sys
from itertools import product

def min_operations(n, m, strings):
    digits = set('0123456789')
    letters = set('abcdefghijklmnopqrstuvwxyz')
    symbols = {'#', '*', '&'}

    has_digit = [i for i in range(n) if any(c in digits for c in strings[i])]
    has_letter = [i for i in range(n) for c in strings[i] if c in letters]
    has_symbol = [i for i in range(n) for c in strings[i] if c in symbols]

    def cost(pos, target_char, s):
        idx = s.index(target_char)
        return min((idx - pos) % m, (pos - idx) % m)

    min_total = float('inf')

    for d in has_digit:
        for l in has_letter:
            if l == d:
                continue
            for s in has_symbol:
                if s == d or s == l:
                    continue
                total = 0
                total += cost(1, strings[d][0], strings[d])
                total += cost(1, strings[l][0], strings[l])
                total += cost(1, strings[s][0], strings[s])
                min_total = min(min_total, total)

    return min_total

def main():
    n, m = map(int, sys.stdin.readline().split())
    strings = [sys.stdin.readline().strip() for _ in range(n)]
    print(min_operations(n, m, strings))

