    item_residents = defaultdict(list)
    for _ in range(k):
        parts = data[idx].split()
        name, typ, bonus, home = parts[0], parts[1], int(parts[2]), parts[3]
        residents.append((name, typ, bonus, home))
        item_residents[home].append((name, typ, bonus))
        idx += 1

    all_residents = {typ: [] for typ in ['gladiator', 'sentry', 'physician']}
    for r in residents:
        name, typ, bonus, _ = r
        all_residents[typ].append((bonus, name))  # store as (bonus, name) to sort by bonus descending

    for typ in all_residents:
        all_residents[typ].sort(reverse=True)

    weapon_candidates = [item for item in items.values() if item['class'] == 'weapon']
    armor_candidates = [item for item in items.values() if item['class'] == 'armor']
    orb_candidates = [item for item in items.values() if item['class'] == 'orb']

