                a_residents = set(r[0] for r in a['residents'])
                o_residents = set(r[0] for r in o['residents'])

                used = w_residents | a_residents | o_residents
                available = [r for r in residents if r[0] not in used]

                gladiators = sorted([r for r in available if r[1] == 'gladiator'], key=lambda x: x[2], reverse=True)
                sentries = sorted([r for r in available if r[1] == 'sentry'], key=lambda x: x[2], reverse=True)
                physicians = sorted([r for r in available if r[1] == 'physician'], key=lambda x: x[2], reverse=True)

                w_slots = w['size'] - len(w_residents)
                a_slots = a['size'] - len(a_residents)
                o_slots = o['size'] - len(o_residents)

                assigned = []

                for i in range(min(w_slots, len(gladiators))):
                    assigned.append(('w', *gladiators[i]))

                for i in range(min(a_slots, len(sentries))):
                    assigned.append(('a', *sentries[i]))

                for i in range(min(o_slots, len(physicians))):
                    assigned.append(('o', *physicians[i]))

                for typ, name, _, home in assigned:
