class SubstrWrapper:
    def __init__(self, s, start, end):
        self.s = s
        self.start = start
        self.end = end

    def __lt__(self, other):
        len_self = self.end - self.start + 1
        len_other = other.end - other.start + 1
        min_len = min(len_self, len_other)
        for i in range(min_len):
            c1 = self.s[self.start + i]
            c2 = other.s[other.start + i]
            if c1 < c2:
                return True
            elif c1 > c2:
                return False
        return len_self < len_other

