def game_result(seq):
    n = len(seq)
    if n == 2:
        return ''.join(seq)

    # Convert to list for easier manipulation
    seq = list(seq)

    def play_turns(seq, turn=0):
        if len(seq) == 2:
            return ''.join(seq)
        if turn % 2 == 0:  # Masha's turn - minimize the result
            min_result = '11'
            for i in range(len(seq)):
