def restore_internet_address(s):
    # Try all possible positions to split the string into protocol, domain, and context
    for i in range(1, len(s)):
        if s[:i] not in ["http", "ftp"]:
            continue
        protocol = s[:i]
        rest = s[i:]
        for j in range(1, len(rest)):
            domain_part = rest[:j]
            if ".ru" not in domain_part:
                continue
            dot_index = domain_part.find(".ru")
