import sys

def restore_address(s):
    # Try all possible positions to split protocol, domain, and context
    for i in range(1, len(s) - 2):
        if s[:i] not in ['http', 'ftp']:
            continue
        protocol = s[:i]
        remaining = s[i:]
        for j in range(1, len(remaining) - 3):
            domain_part = remaining[:j]
            if '.' not in domain_part:
                continue
            dot_index = domain_part.rfind('.')
            domain = domain_part[:dot_index]
            rest = domain_part[dot_index:] + remaining[j:]
            if not rest:
                return f"{protocol}://{domain}.ru"
            for k in range(1, len(rest) + 1):
                context = rest[:k]
                if context.isalpha():
                    return f"{protocol}://{domain}.ru/{context}"
        for j in range(1, len(remaining)):
            domain = remaining[:j]
            if domain.isalpha():
                return f"{protocol}://{domain}.ru"
    return ""

if __name__ == "__main__":
    s = sys.stdin.readline().strip()
    print(restore_address(s))

