import math

def catalan(n):
    return math.comb(2 * n, n) / (n + 1)

def solve():
    import sys
    sys.setrecursionlimit(1000000)
    from functools import lru_cache

    n, m, k = map(int, sys.stdin.readline().split())

    if m > n + k:
        print("0.0")
        return

    total_people = n + m
    total_ways = math.comb(total_people, n)

    @lru_cache(None)
    def dp(i, ten_notes):
        if i == total_people:
            return 1.0
        res = 0.0
        for choice in [0, 1]:
            if choice == 0 and n > 0:  # person with 10 euros
                res += dp(i + 1, ten_notes + 1)
            elif choice == 1 and m > 0 and ten_notes > 0:  # person with 20 euros
                res += dp(i + 1, ten_notes - 1)
        return res

    valid_sequences = dp(0, k)
    probability = valid_sequences / total_ways
    print(f"{probability:.10f}")

if __name__ == "__main__":
    solve()

