class FenwickTree:
    def __init__(self, size):
        self.n = size
        self.tree = [0] * (self.n + 1)  # 1-based indexing

    def update(self, idx, value):
        while idx <= self.n:
            if self.tree[idx] < value:
                self.tree[idx] = value
            else:
                break
            idx += idx & -idx

    def query(self, idx):
        res = 0
        while idx > 0:
            if self.tree[idx] > res:
                res = self.tree[idx]
            idx -= idx & -idx
        return res

def main():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    n = int(input[ptr])
    ptr += 1
    m = int(input[ptr])
    ptr += 1
    s = []
    for _ in range(n):
        si = int(input[ptr])
        ptr += 1
        # xi = float(input[ptr])
        ptr += 1
        s.append(si)

    ft = FenwickTree(m)
    max_len = 0
    for num in s:
        q = ft.query(num)
        new_val = q + 1
        ft.update(num, new_val)
        if new_val > max_len:
            max_len = new_val
    print(n - max_len)

if __name__ == "__main__":
    main()

