import sys
from collections import defaultdict, deque

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    edges = []
    cities = set()

    for i in range(n):
        a = int(data[2 * i + 1])
        b = int(data[2 * i + 2])
        edges.append((a, b))
        cities.add(a)
        cities.add(b)

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    start = None
    for u, v in edges:
        if len(graph[u]) == 1:
            start = u
            break
    if start is None:
        for u, v in edges:
            if len(graph[v]) == 1:
                start = v
                break

    visited = set()
    path = []

    def dfs(node):
        visited.add(node)
        path.append(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                dfs(neighbor)

    dfs(start)
    print(' '.join(map(str, path)))

if __name__ == "__main__":
    main()

