    input = sys.stdin.read
    data = input().splitlines()

    s = list(data[0])
    m = s.count('?')

    costs = []
    idx = 0
    for ch in s:
        if ch == '?':
            a = int(data[1 + idx][0])
            b = int(data[1 + idx][1])
            costs.append((a, b))
            idx += 1

    n = len(s)
    stack = []
    res = s[:]
    total_cost = 0
    heap = []

    i = 0
    open_needed = 0
    close_heap = []

    for i in range(n):
        if s[i] == '(' or s[i] == '?':
            if s[i] == '?':
                heapq.heappush(heap, (costs[0][0] - costs[0][1], i, 0))  # (cost_diff, index, type: 0=open, 1=close)
                costs.pop(0)
            stack.append(i)
        elif s[i] == ')':
            if not stack:
                print(-1)
                return
            j = stack.pop()
            res[i] = ')'
            if s[j] == '?':
                cost_diff, pos, t = heapq.heappop(heap)
                if cost_diff <= 0:
                    res[pos] = '('
                    total_cost += costs[pos - j - 1][0]
                else:
                    res[pos] = ')'
                    total_cost += costs[pos - j - 1][1]

    if len(stack) % 2 != 0:
        print(-1)
        return

    while stack:
        i1 = stack.pop()
        i2 = stack.pop()
        if res[i1] != ')':
