def main():
    import sys
    input = sys.stdin.read
    n, m = map(int, input().split())
    x = int(input().split()[1])

    def count_repaints(x):
        if x == 0:
            return n * m // 2 + (n * m % 2)
        level = x - 1
        min_dim = min(n, m)
        max_level = (min_dim - 1) // 2
        if level > max_level:
            return 0
        cnt = (n - 2 * level) * (m - 2 * level) - (n - 2 * (level + 1)) * (m - 2 * (level + 1))
        return cnt

    print(count_repaints(x))

