    visited = [[False]*cols for _ in range(rows)]
    enclosed_areas = 0
    total_areas = 0

    def bfs(r, c):
        nonlocal enclosed_areas, total_areas
        queue = [(r, c)]
        visited[r][c] = True
        is_enclosed = True
        area_cells = []
        while queue:
            x, y = queue.pop()
            area_cells.append((x, y))
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < cols:
                    if not visited[nx][ny] and grid[nx][ny] == '.':
                        visited[nx][ny] = True
                        queue.append((nx, ny))
                    elif not visited[nx][ny] and grid[nx][ny] != '.':
                        visited[nx][ny] = True
                    else:
                        continue
                else:
                    is_enclosed = False
        total_areas += 1
        if is_enclosed:
            enclosed_areas += 1

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '.' and not visited[i][j]:
