    n = int(sys.stdin.readline())

    # Use dynamic programming to calculate the expected number of tosses
    from fractions import Fraction

    memo = {}

    def dp(n):
        if n == 1:
            return Fraction(0)
        if n in memo:
            return memo[n]

        min_expected = Fraction('inf')
        for k in range(1, n.bit_length() + 1):  # Try all possible numbers of coin tosses
            total = 0
            for i in range(2**k):
                rem = n - (i * (2**k) // n)
                total += dp(rem)
            expected = Fraction(k) + Fraction(total, n)
            if expected < min_expected:
                min_expected = expected
        memo[n] = min_expected
        return min_expected

    result = dp(n)

    numerator = result.numerator
    denominator = result.denominator

    print(f"{numerator}/{denominator}")

if __name__ == "__main__":
