    n = int(sys.stdin.readline())
    graph = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u, v = map(int, sys.stdin.readline().split())
        graph[u].append(v)
        graph[v].append(u)

    color = [0] * (n + 1)
    max_degree = 0

    for i in range(1, n + 1):
        max_degree = max(max_degree, len(graph[i]))

    def bfs_coloring(start):
        queue = deque([start])
        color[start] = 1
        while queue:
            u = queue.popleft()
            used_colors = set()
            for v in graph[u]:
                if color[v] != 0:
                    used_colors.add(color[v])
            next_color = 1
            for v in graph[u]:
                if color[v] == 0:
                    while next_color in used_colors:
                        next_color += 1
                    color[v] = next_color
                    used_colors.add(next_color)
                    queue.append(v)
                    next_color += 1

    for i in range(1, n + 1):
        if color[i] == 0:
            bfs_coloring(i)

    print(max(color))
    print(' '.join(map(str, color[1:])))

