def main():
    import sys
    input = sys.stdin.readline
    print_flush = lambda *args: print(*args, flush=True)

    n, x, y = map(int, input().split())

    xor_x_y = x ^ y

    # Find a bit where x and y differ
    diff_bit = 0
    while (xor_x_y >> diff_bit) & 1 == 0:
        diff_bit += 1

    group1 = []
    group2 = []

    for i in range(1, n + 1):
        if ((x >> diff_bit) & 1) == 0:
            group1.append(i)
        else:
            group2.append(i)

    print_flush("?", len(group1), *group1)
    res = int(input())
    if res == -1:
        exit()

    expected = (len(group1) % 2) * (x ^ y)
    if res != expected:
        # The two special icicles are in different groups
        # Try to find one in each group
