            if r == y:
                idx1 = i
                break

        for i in group2:
            print_flush("?", 1, i)
            r = int(input())
            if r == -1:
                exit()
            if r == y:
                idx2 = i
                break
        print_flush("!", min(idx1, idx2), max(idx1, idx2))
    else:
        # Both special icicles are in the same group
        # Recurse into that group
