            expected_left = (len(left) % 2) * (x ^ y)
            if res_left != expected_left:
                idx1, idx2 = find_two_specials(left)
            else:
                idx1, idx2 = find_two_specials(right)
            return idx1, idx2

        idx1, idx2 = find_two_specials(group1 if len(group1) > 1 else group2)
        print_flush("!", min(idx1, idx2), max(idx1, idx2))

if __name__ == "__main__":
