    input = sys.stdin.readline
    n, x, y = map(int, input().split())

    # Find the XOR of all icicles if there were only x's
    expected_xor = 0
    for i in range(1, n + 1):
        expected_xor ^= x

    # Actual XOR will differ by (x ^ y) * 2 because two positions are different
    xor_diff = x ^ y

    # We need to find which two indices differ from x to y
    special_indices = []

    for bit in range(30):  # since max value is up to 1e9 (~2^30)
        if (xor_diff >> bit) & 1:
            # This bit is different between x and y
            mask = 1 << bit
            subset = []
            for i in range(1, n + 1):
                if (i - 1) & mask:
                    subset.append(i)

            print(f"? {len(subset)} {' '.join(map(str, subset))}")
            sys.stdout.flush()
            res = int(input())

            if res != 0:
                # One of the special icicles is in this subset
                for idx in subset:
                    if idx not in special_indices:
                        special_indices.append(idx)
            else:
                # The other one is outside
                for idx in range(1, n + 1):
                    if idx not in subset and idx not in special_indices:
                        special_indices.append(idx)
                        break

            if len(special_indices) == 2:
                break

    print(f"! {special_indices[0]} {special_indices[1]}")
    sys.stdout.flush()

if __name__ == "__main__":
    main()

